import {ToolRegistry} from './registry.js';
import type {ToolDefinitionSource} from './registry.js';

const requiresLocation = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};

function recordingRegistry(source: ToolDefinitionSource) {
  const registry = new ToolRegistry();
  const inputs: Array<Record<string, unknown>> = [];
  registry.register(source, async input => {
    inputs.push(input);
    return 'sunny';
  });
  return {registry, inputs};
}

describe('ToolRegistry.execute input validation', () => {
  it('names a missing required property and never calls the executor', async () => {
    const {registry, inputs} = recordingRegistry({
      name: 'get_weather',
      description: 'w',
      inputSchema: requiresLocation,
    });

    const response = await registry.execute('get_weather', {});

    expect({inputs, result: response.result}).toEqual({
      inputs: [],
      result: "Invalid input for tool get_weather: 'location' is required",
    });
  });
});

describe('ToolRegistry.register schema compilation', () => {
  it('throws naming the tool when a static inputSchema has a malformed required list', () => {
    const malformed = {type: 'object', required: 'location'};

    expect(() => recordingRegistry({name: 'bad_required', description: 'b', inputSchema: malformed})).toThrow(
      'Invalid inputSchema for tool bad_required: schema/required must be array'
    );
  });
});

